mapper.select:
SELECT id, device_id, device_code, event_type, payload::text AS payload,
       run_id, source_event_id, process_id, interaction_step, created_at
  FROM device_event
 WHERE tenant_id = #{tenantId}
   AND id > #{afterId}

   AND device_code = #{deviceCode}


   AND event_type = #{eventType}



   AND created_at >= #{sinceTs}


   AND created_at <= #{untilTs}

 ORDER BY id
 LIMIT #{limit}

WITH existing AS (
    SELECT c.event_id
      FROM device_event_consumption c
     WHERE c.tenant_id = #{tenantId}
       AND c.run_id = #{runId}
       AND c.node_key = #{nodeKey}
       AND c.loop_index = #{loopIndex}
), candidate AS (
    SELECT e.id
      FROM device_event e
     WHERE e.tenant_id = #{tenantId}
       AND e.id > #{afterId}
       AND e.dispatched_at IS NULL
       AND NOT EXISTS (SELECT 1 FROM existing)
       AND NOT EXISTS (SELECT 1 FROM device_event_consumption c
                        WHERE c.event_id = e.id)

       AND e.device_code = #{deviceCode}


       AND e.event_type = #{eventType}

     ORDER BY e.id
     LIMIT 1
     FOR UPDATE SKIP LOCKED
), claimed AS (
    INSERT INTO device_event_consumption
        (event_id, tenant_id, run_id, node_key, loop_index)
    SELECT id, #{tenantId}, #{runId}, #{nodeKey}, #{loopIndex}
      FROM candidate
    ON CONFLICT DO NOTHING
    RETURNING event_id
), selected AS (
    SELECT event_id FROM claimed
    UNION ALL
    SELECT event_id FROM existing
    LIMIT 1
), touched AS (
    UPDATE device_event e
       SET dispatched_at = COALESCE(e.dispatched_at, now()),
           attempts = e.attempts + 1,
           last_error = NULL
      FROM selected s
     WHERE e.id = s.event_id
       AND e.tenant_id = #{tenantId}
    RETURNING e.id, e.device_id, e.device_code, e.event_type,
              e.payload::text AS payload, e.run_id, e.source_event_id,
              e.process_id, e.interaction_step, e.created_at
)
SELECT * FROM touched

mapper.update:
UPDATE device_event
   SET dispatched_at = COALESCE(dispatched_at, now()), attempts = attempts + 1
 WHERE tenant_id = #{tenantId} AND id = #{id}
